# frozen_string_literal: true

require "timeout"
require "yamlcamel"
require_relative "generator"

module YAMLCamelSpec
  # Feeds mutated and generated bytes to the parser and holds every answer to the same contract: a
  # value or a YAMLCamel::Error, inside a time budget, without the process growing without bound.
  #
  # Ruby has no libFuzzer binding, so coverage comes from a starting corpus and mutation rather than
  # from instrumentation. The corpus is the same set of adversarial files the unit suite walks.
  class Fuzzer
    Finding = Struct.new(:kind, :seed, :detail, :input)

    # How long one input may take before the parser is considered hung.
    ATTEMPT_TIMEOUT = 10

    # How far resident memory may grow across a run, in megabytes, for input this size.
    MEMORY_CEILING_MB = 600

    attr_reader :findings, :attempts

    def initialize(seed:, corpus: [], parse_limits: YAMLCamel::Limits.default,
                   attempt_timeout: ATTEMPT_TIMEOUT)
      @base_seed = seed
      @corpus = corpus
      @limits = parse_limits
      @attempt_timeout = attempt_timeout
      @findings = []
      @attempts = 0
    end

    # Runs until the budget in seconds runs out or the iteration cap is reached, whichever is first.
    def run(seconds: nil, iterations: nil)
      started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      baseline = resident_mb
      index = 0
      loop do
        break if iterations && index >= iterations
        break if seconds && Process.clock_gettime(Process::CLOCK_MONOTONIC) - started >= seconds

        attempt(@base_seed + index)
        index += 1
        check_memory(baseline) if (index % 500).zero?
      end
      check_memory(baseline)
      @findings
    end

    def attempt(seed)
      @attempts += 1
      input = build_input(seed)
      begin
        Timeout.timeout(@attempt_timeout) { check_one(input) }
      rescue YAMLCamel::Error
        nil
      rescue Timeout::Error
        record(:hang, seed, "no answer in #{@attempt_timeout}s", input)
      rescue StandardError, SystemStackError => e
        record(:leaked, seed, "#{e.class}: #{e.message}", input)
      end
    end

    private

    # What a round trip is allowed to cost. Aliases let a few hundred bytes parse into tens of
    # megabytes of text, and stringifying those buys no coverage the small cases do not already give.
    ROUND_TRIP_LIMITS = YAMLCamel::EmitLimits.new(max_output_bytes: 1 << 20, max_nodes: 50_000)

    # Every property one input is held to. A refusal is a fine answer, so only the checks that follow
    # a successful parse assert anything about the value.
    def check_one(input)
      documents = check_streaming(input)
      documents.each do |document|
        emitted = begin
          YAMLCamel.dump(document, limits: ROUND_TRIP_LIMITS)
        rescue YAMLCamel::EmitError
          next
        end

        back = YAMLCamel.load(emitted, limits: YAMLCamel::Limits.permissive)
        again = YAMLCamel.dump(back, limits: ROUND_TRIP_LIMITS)
        next if again == emitted

        raise RoundTripError, "emit and parse changed the value:\n#{emitted}\nbecame\n#{again}"
      end
    end

    class RoundTripError < StandardError; end

    # Reads the input whole and again a chunk at a time, and holds the two to the same answer. Where
    # a chunk boundary falls is transport, so it cannot decide what a reader produces.
    def check_streaming(input)
      whole = capture { YAMLCamel.load_stream(input, limits: @limits) }
      chunk = 1 + (input.bytesize % 32)
      streamed = capture do
        documents = []
        stream = YAMLCamel::DocumentStream.new(limits: @limits) { |document| documents << document }
        input.b.chars.each_slice(chunk) { |slice| stream.push(slice.join) }
        stream.finish
        documents
      end

      unless same_outcome?(whole, streamed)
        raise RoundTripError,
              "reading in chunks of #{chunk} answered #{describe(streamed)} where reading whole " \
              "answered #{describe(whole)}"
      end
      raise whole[1] if whole[0] == :error

      whole[1]
    end

    def capture
      [:ok, yield]
    rescue YAMLCamel::Error => e
      [:error, e]
    end

    # Errors compare by class rather than by message, since the two readers count lines from
    # different places in the same stream.
    def same_outcome?(left, right)
      if left[0] == :error && right[0] == :error
        # Whole input can reject malformed bytes before parsing; an incremental reader may
        # encounter a resource bound in a valid earlier prefix before those bytes arrive.
        if left[1].is_a?(YAMLCamel::SyntaxError) || right[1].is_a?(YAMLCamel::SyntaxError)
          return left[1].is_a?(YAMLCamel::ParseError) && right[1].is_a?(YAMLCamel::ParseError)
        end
        return left[1].class == right[1].class
      end
      return false unless left[0] == :ok && right[0] == :ok

      left[1].length == right[1].length &&
        left[1].zip(right[1]).all? { |a, b| same_document?(a, b) }
    end

    def same_document?(left, right)
      YAMLCamel.dump(left, limits: ROUND_TRIP_LIMITS) == YAMLCamel.dump(right, limits: ROUND_TRIP_LIMITS)
    rescue YAMLCamel::EmitError
      true
    end

    def describe(outcome) = outcome[0] == :error ? outcome[1].class.name : "#{outcome[1].length} document(s)"

    def build_input(seed)
      generator = Generator.new(seed)
      case seed % 6
      when 0 then generator.soup
      when 1 then generator.bytes(max_length: 400)
      when 2 then mutate(generator, seed_input(generator))
      when 3 then mutate(generator, mutate(generator, seed_input(generator)))
      when 4 then YAMLCamel.dump(generator.value)
      else mutate(generator, YAMLCamel.dump(generator.value))
      end
    end

    def seed_input(generator)
      return generator.soup if @corpus.empty?

      generator.pick(@corpus)
    end

    # One structural edit, the kind a coverage-guided fuzzer would make: a flipped byte, an inserted
    # or deleted run, a duplicated chunk, or a truncation.
    def mutate(generator, text)
      bytes = text.b
      return bytes if bytes.empty?

      case generator.integer(0..5)
      when 0
        at = generator.integer(0...bytes.bytesize)
        bytes.setbyte(at, generator.integer(0..255))
        bytes
      when 1
        at = generator.integer(0..bytes.bytesize)
        bytes.byteslice(0, at).to_s + generator.pick(Generator::SOUP_PIECES).b + bytes.byteslice(at..).to_s
      when 2
        at = generator.integer(0...bytes.bytesize)
        width = generator.integer(1..[16, bytes.bytesize - at].min)
        bytes.byteslice(0, at).to_s + bytes.byteslice((at + width)..).to_s
      when 3
        at = generator.integer(0...bytes.bytesize)
        width = generator.integer(1..[64, bytes.bytesize - at].min)
        chunk = bytes.byteslice(at, width).to_s
        bytes.byteslice(0, at).to_s + (chunk * generator.integer(2..4)) + bytes.byteslice((at + width)..).to_s
      when 4
        bytes.byteslice(0, generator.integer(0..bytes.bytesize)).to_s
      else
        bytes + generator.pick(Generator::SOUP_PIECES).b
      end
    end

    def record(kind, seed, detail, input)
      @findings << Finding.new(kind, seed, detail, input)
    end

    def check_memory(baseline)
      return if baseline.nil?

      now = resident_mb
      return if now.nil? || now - baseline <= MEMORY_CEILING_MB

      record(:memory, @base_seed, "resident memory grew #{(now - baseline).round} MB", nil)
    end

    # Resident size in megabytes, or nil where the platform does not answer.
    def resident_mb
      if File.exist?("/proc/self/statm")
        pages = File.read("/proc/self/statm").split[1].to_i
        return pages * 4096 / (1024.0 * 1024)
      end

      output = `ps -o rss= -p #{Process.pid} 2>/dev/null`
      output.strip.empty? ? nil : output.to_i / 1024.0
    end
  end
end
